def replace_expressions(self, replacements):
    if not replacements:
        return self
    if self in replacements:
        replacement = replacements[self]
        if replacement is not None:
            # Ensure replacements are applied recursively, considering replacements
            return replacement.replace_expressions(replacements)
        return replacement
    if not (source_expressions := self.get_source_expressions()):
        return self
    clone = self.copy()
    clone.set_source_expressions(
        [
            expr.replace_expressions(replacements) if expr is not None else None
            for expr in source_expressions
        ]
    )
    return clone
